// Pedidos de alteração → planilha da Central. Reserva até 5 pedidos aprovados com planilha pendente.
// Sem pedido, não devolve nada e o fluxo para aqui.
const URL = 'https://mbvybujpkwuorhtdzcde.supabase.co/rest/v1/rpc/';
const H = { apikey: '<SUPABASE_ANON_KEY>', Authorization: 'Bearer <SUPABASE_ANON_KEY>', 'Content-Type': 'application/json' };
const SEG = '<SEGREDO_N8N>';
const rpc = (fn, body) => this.helpers.httpRequest({ method: 'POST', url: URL + fn, headers: H, body, json: true });
const r = await rpc('pa_planilha_reservar', { p_segredo: SEG });
if (!r || !r.ok) throw new Error('pa_planilha_reservar recusou (segredo?)');
if (!r.planilha_id || !(r.pedidos || []).length) return [];
const base = 'https://sheets.googleapis.com/v4/spreadsheets/' + r.planilha_id;
const rg = [r.abas.central, r.abas.removidos].map(a => 'ranges=' + encodeURIComponent("'" + a.replace(/'/g, "''") + "'")).join('&');
return [{ json: { ...r, base,
  url_abas: base + '?fields=' + encodeURIComponent('sheets.properties(sheetId,title)'),
  url_texto: base + '/values:batchGet?' + rg + '&valueRenderOption=FORMATTED_VALUE',
  url_formula: base + '/values:batchGet?' + rg + '&valueRenderOption=FORMULA' } }];

// Planeja a escrita dos pedidos de alteração na planilha da Central (corpo do node "Planejar" do n8n).
// Entrada: res = resposta de pa_planilha_reservar; fmt/fml = valueRanges (Central, Removidos) em FORMATTED_VALUE e FORMULA;
// sheets = [{sheetId,title}]. Saída: {dados (values.batchUpdate), apagar (deleteDimension), resultados [{pedido,ok,erro,detalhe}]}.
// Nada é escrito se a linha não for achada com certeza; detalhe leva só linha, coluna e aba, nunca valor de célula.
function planejar(res, fmt, fml, sheets) {
  const ABA_C = res.abas.central, ABA_R = res.abas.removidos;
  const CAB_C = res.cabecalhos[ABA_C], CAB_R = res.cabecalhos[ABA_R];
  const col2i = (l) => [...l].reduce((n, ch) => n * 26 + ch.charCodeAt(0) - 64, 0) - 1;
  const i2col = (i) => { let s = ''; i++; while (i > 0) { const m = (i - 1) % 26; s = String.fromCharCode(65 + m) + s; i = Math.floor((i - 1) / 26); } return s; };
  const q = (aba) => "'" + aba.replace(/'/g, "''") + "'";
  const C = (fmt[0].values || []).map((r) => r.slice());
  const F = (fml[0].values || []);
  const R = (fmt[1].values || []);
  const norm = (v) => String(v ?? '').trim().replace(/\s+/g, ' ').toLowerCase();
  const dig = (v) => String(v ?? '').replace(/\D/g, '');
  const docN = (v) => { const d = dig(v); return d.length === 10 ? '0' + d : d; };

  // 1. Cabeçalhos: qualquer diferença trava a rodada inteira.
  const confere = (linha1, mapa, aba) => Object.entries(mapa)
    .filter(([cab, l]) => String((linha1 || [])[col2i(l)] ?? '').trim() !== cab)
    .map(([cab, l]) => aba + '!' + l + ' (esperado "' + cab + '")');
  const difs = [...confere(C[0], CAB_C, ABA_C), ...confere(R[0], CAB_R, ABA_R)];
  if (difs.length) {
    return { dados: [], apagar: [], resultados: res.pedidos.map((p) => ({ pedido: p.pedido, ok: false,
      erro: 'Cabeçalho da planilha mudou: ' + difs.join('; ').slice(0, 400), detalhe: { cabecalho: difs } })) };
  }
  const largura = Math.max(...Object.values(CAB_C).map(col2i)) + 1;
  const ultimaCol = Math.max(largura, ...C.map((r) => r.length), ...F.map((r) => r.length));
  const ic = (cab) => col2i(CAB_C[cab]);
  const apagadas = new Set();

  // Linhas (1-based) cujo e-mail (qualquer parte de "novo / antigo") ou documento bate com as chaves.
  const achar = (ch) => {
    const em = new Set((ch?.emails || []).map(norm)), dc = new Set((ch?.documentos || []).map(docN));
    const out = [];
    for (let r = 1; r < C.length; r++) {
      if (apagadas.has(r + 1)) continue;
      const row = C[r] || [];
      const emails = String(row[ic('Email')] ?? '').split('/').map(norm).filter(Boolean);
      const doc = docN(row[ic('Documento')]);
      if (emails.some((e) => em.has(e)) || (doc.length >= 11 && dc.has(doc))) out.push(r + 1);
    }
    return out;
  };
  const cel = (linha, cab) => String((C[linha - 1] || [])[ic(cab)] ?? '');
  const ehFormula = (linha, i) => String((F[linha - 1] || [])[i] ?? '').startsWith('=');
  // Texto para USER_ENTERED: nunca vira fórmula; número longo (documento, telefone, CEP) fica texto.
  const val = (cab, v) => {
    v = String(v ?? '');
    if (/^[=+\-@]/.test(v)) return "'" + v;
    if (['Documento', 'Telefone', 'CEP'].includes(cab) && /^\d+$/.test(v)) return "'" + v;
    return v;
  };
  const igual = (cab, planilha, esperado) => {
    if (cab === 'Documento') return docN(planilha) === docN(esperado);
    if (cab === 'Telefone') { const a = dig(planilha), b = dig(esperado); return a === b || (a && b && (a.endsWith(b) || b.endsWith(a))); }
    if (cab === 'Email') return norm(String(planilha).split('/')[0]) === norm(esperado);
    return norm(planilha) === norm(esperado);
  };

  const dados = [], apagar = [], resultados = [];
  let proxRem = R.length + 1; // primeira linha vazia de Removidos
  while (proxRem > 2 && !(R[proxRem - 2] || []).some((x) => String(x).trim())) proxRem--;
  const escreve = (linha, cab, v, cols) => {
    const i = ic(cab); const vv = val(cab, v);
    (C[linha - 1] = C[linha - 1] || [])[i] = String(v ?? '');
    dados.push({ range: q(ABA_C) + '!' + CAB_C[cab] + linha, values: [[vv]] }); cols.push(CAB_C[cab]);
  };
  const umaLinha = (ch, quem) => {
    const l = achar(ch);
    if (l.length !== 1) throw new Error(l.length + ' linhas para ' + quem + ' (e-mail/documento)');
    return l[0];
  };

  for (const p of res.pedidos) {
    const base = dados.length;
    try {
      if (p.erro) throw new Error(p.erro);
      if (p.tipo === 'alterar_dado') {
        if (p.sem_coluna) { resultados.push({ pedido: p.pedido, ok: true, erro: null, detalhe: { sem_coluna: true, campo: p.campo } }); continue; }
        const linha = umaLinha(p.aluno.chaves, 'o aluno');
        const dif = Object.entries(p.esperado_antes).filter(([cab, v]) => !igual(cab, cel(linha, cab), v)).map(([cab]) => CAB_C[cab]);
        if (dif.length) throw new Error('Célula diferente do valor antigo na linha ' + linha + ', coluna ' + dif.join(', '));
        const cols = [];
        for (const [cab, v] of Object.entries(p.escrever)) escreve(linha, cab, v, cols);
        resultados.push({ pedido: p.pedido, ok: true, erro: null, detalhe: { aba: ABA_C, linha, colunas: cols } });
        continue;
      }
      // trocar_socio
      const lt = umaLinha(p.titular.chaves, 'o titular');
      const ls = umaLinha(p.sai.chaves, 'quem sai');
      const le = achar(p.entra.chaves);
      if (le.length > 1) throw new Error(le.length + ' linhas para quem entra (e-mail/documento)');
      if (le[0] === ls || ls === lt || le[0] === lt) throw new Error('Titular, quem sai e quem entra caem na mesma linha');
      const entra = le[0] || null;
      if (!entra && !p.entra.chaves.emails.length && !p.entra.chaves.documentos.length) throw new Error('Quem entra sem e-mail nem documento no sistema');
      if (!entra) { // sem chave igual, mas com o mesmo nome: pode ser a mesma pessoa com outro e-mail; conferência humana
        const mesmoNome = [];
        for (let r = 1; r < C.length; r++) if (!apagadas.has(r + 1) && norm((C[r] || [])[ic('Nome')]) === norm(p.entra.nome)) mesmoNome.push(r + 1);
        if (mesmoNome.length) throw new Error('Quem entra não casa por e-mail/documento, mas a linha ' + mesmoNome.join(', ') + ' tem o mesmo nome: conferir');
      }

      // Removidos: copia a linha de quem sai antes de mexer nela.
      const rem = [];
      for (const [cab, l] of Object.entries(CAB_R)) {
        let v = '';
        if (cab === 'Linha na Central') v = String(ls);
        else if (p.copiar_para_removidos[cab]) v = cel(ls, p.copiar_para_removidos[cab]);
        else if (cab in p.removidos) v = p.removidos[cab];
        rem[col2i(l)] = val(cab === 'E-mail' ? 'Email' : cab, v);
      }
      const linhaRem = proxRem++;
      dados.push({ range: q(ABA_R) + '!A' + linhaRem + ':' + i2col(rem.length - 1) + linhaRem, values: [Array.from(rem, (x) => x ?? '')] });

      const cols = [];
      const tit = {}; for (const cab of Object.keys(CAB_C)) tit[cab] = cel(lt, cab);
      let acao, alvo;
      if (!entra) {
        acao = 'sobrescreveu a linha de quem sai'; alvo = ls;
        const esc = { ...p.se_entra_sem_linha.escrever };
        for (const cab of p.se_entra_sem_linha.copiar_do_titular) esc[cab] = tit[cab];
        // Demais colunas vazias, sem tocar em fórmula.
        const usadas = new Set(Object.keys(esc).map(ic));
        for (const [cab, v] of Object.entries(esc)) escreve(ls, cab, v, cols);
        const vazias = [];
        for (let i = 0; i < ultimaCol; i++) {
          if (usadas.has(i) || ehFormula(ls, i)) continue;
          if (String((C[ls - 1] || [])[i] ?? '') === '' ) continue;
          (C[ls - 1])[i] = ''; vazias.push(i2col(i));
          dados.push({ range: q(ABA_C) + '!' + i2col(i) + ls, values: [['']] });
        }
        if (vazias.length) cols.push('limpou:' + vazias.join(','));
      } else {
        acao = 'apagou a linha de quem sai'; alvo = entra;
        const esc = { ...p.se_entra_com_linha.escrever };
        for (const cab of p.se_entra_com_linha.copiar_do_titular) esc[cab] = tit[cab];
        for (const [cab, v] of Object.entries(esc)) escreve(entra, cab, v, cols);
        apagadas.add(ls); apagar.push(ls);
      }
      for (const [cab, v] of Object.entries(p.titular.escrever)) escreve(lt, cab, v, []);
      resultados.push({ pedido: p.pedido, ok: true, erro: null, detalhe: {
        aba: ABA_C, acao, linha_titular: lt, linha_sai: ls, linha_entra: entra, linha_alvo: alvo,
        removidos_linha: linhaRem, colunas: cols } });
    } catch (e) {
      dados.splice(base); // nada do pedido com erro é escrito
      resultados.push({ pedido: p.pedido, ok: false, erro: String(e.message || e).slice(0, 400), detalhe: null });
    }
  }
  // Apagar por último, de baixo para cima (as escritas acima usam a numeração de antes).
  const sid = sheets.find((s) => s.title === ABA_C).sheetId;
  const apagarReq = [...new Set(apagar)].sort((a, b) => b - a)
    .map((l) => ({ deleteDimension: { range: { sheetId: sid, dimension: 'ROWS', startIndex: l - 1, endIndex: l } } }));
  return { dados, apagar: apagarReq, resultados };
}


const res = $('Reservar').first().json;
const sheets = $('Abas').first().json.sheets.map(s => s.properties);
const out = planejar(res, $('Ler texto').first().json.valueRanges, $('Ler fórmulas').first().json.valueRanges, sheets);
return [{ json: { ...out, tem_escrita: out.dados.length > 0, tem_apagar: out.apagar.length > 0 } }];

// Devolve ao banco o resultado de cada pedido. Falha do Google vira erro do pedido (conferência humana), nunca nova tentativa:
// uma segunda rodada repetiria a linha em Removidos.
const URL = 'https://mbvybujpkwuorhtdzcde.supabase.co/rest/v1/rpc/';
const H = { apikey: '<SUPABASE_ANON_KEY>', Authorization: 'Bearer <SUPABASE_ANON_KEY>', 'Content-Type': 'application/json' };
const SEG = '<SEGREDO_N8N>';
const rpc = (fn, body) => this.helpers.httpRequest({ method: 'POST', url: URL + fn, headers: H, body, json: true });
const plano = $('Planejar').first().json;
const falha = (no) => { try { if (!$(no).isExecuted) return null; const j = $(no).first().json; return j.error ? String(j.error.message || JSON.stringify(j.error)).slice(0, 200) : null; } catch (e) { return null; } };
const fEsc = falha('Escrever'), fApg = falha('Apagar linhas');
const out = [];
for (const r of plano.resultados) {
  let ok = r.ok, erro = r.erro, det = r.detalhe;
  if (ok && det && (det.linha_titular !== undefined || det.linha !== undefined)) {
    if (fEsc) { ok = false; erro = 'O Google recusou a escrita, nada foi gravado: ' + fEsc; }
    else if (fApg && det.acao === 'apagou a linha de quem sai') { ok = false; erro = 'Escreveu, mas não apagou a linha ' + det.linha_sai + ' de quem sai: apagar à mão. ' + fApg; }
  }
  const c = await rpc('pa_planilha_confirmar', { p_segredo: SEG, p_pedido: r.pedido, p_ok: ok, p_erro: erro, p_detalhe: det });
  out.push({ pedido: r.pedido, ok, erro, confirmado: !!(c && c.ok) });
}
return [{ json: { pedidos: out } }];
